import codecs
import _codecs
seen = []
def search(name):
    seen.append(name)
    return None
codecs.register(search)
for name in ('bad\0name', 'bad\0\ud800'):
    for action in (lambda: codecs.lookup(name), lambda: codecs.lookup_error(name), lambda: codecs.register_error(name, None), lambda: _codecs._unregister_error(name), lambda: codecs.encode('', name), lambda: codecs.decode(b'', name), lambda: ''.encode(name), lambda: b''.decode(name), lambda: ''.encode('utf8', name), lambda: b''.decode('utf8', name)):
        try:
            action()
        except Exception as error:
            print(type(error).__name__, error.args)
print('searches', seen)
class Position:
    def __index__(self):
        print('index')
        assert input() == 'continue'
        return -1
def handler(error):
    print('handler', error.encoding, error.start, error.end)
    return ('?', Position())
codecs.register_error('name-service', handler)
print(codecs.decode(b'\xffZ', 'ascii', 'name-service'))
print(codecs.lookup('UTF-8') is codecs.lookup('utf8'))
